"{0}: LMB — lob at the aim point, RMB — high view, {1} — flare bomb (spotting).":"{0}. ձախ կոճակ — կրակոց կորագիծ հետագծով նշանառության կետում, աջ կոճակ — տեսք վերևից, {1} — լուսավորող ռումբ (հետախուզություն)։",
