"Anyone remember why the sky is a portal?":"Որևէ մեկը հիշո՞ւմ է, թե ինչու է երկինքը պորտալ։",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Ասում են՝ եթե ցատկես հորը, թշնամու մոտ դուրս կգաս։ Չեմ ստուգի։",
"The Swarm painted their visors red again. Show-offs.":"Գալաքները նորից կարմիր են ներկել երեսկալները։ Պարծենկոտներ։",
"Ore, ore… when do we get some oil?":"Հանքաքար, հանքաքար... իսկ քսայուղը ե՞րբ կտան։",
"I dreamt I was a toaster. It was peaceful.":"Երազում տեսա, թե տոստեր եմ։ Խաղաղ էր։",
"Quiet. Too quiet.":"Հանգիստ է։ Չափազանց հանգիստ։",
"See that? Our base is above the Swarm base again. Portals, man.":"Տեսաք՞։ Նանձի բազայի վերևում նորից մեր բազան է։ Պորտալ, գրողը տանի։",
"Diman, if you're reading this — we need a vacation.":"Դիման, եթե սա կարդում ես՝ մեզ արձակուրդ է պետք։",
