"Not a Portal Meteor save or an unsupported version":"Ֆայլը Portal Meteor-ից չէ կամ հնացած տարբերակի է",
"Browser storage is full":"Բրաուզերի պահոցում տեղ չբավականացրեց",
"Battle loaded: {0}":"Մարտը բեռնվեց՝ {0}",
"Autosaved":"Ինքնապահպանվեց",
"robot war · the sky is a portal":"ռոբոտների պատերազմ · երկինքը պորտալ է",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Բարի գալուստ երկնաքար։ Դու Կոնսորցիումի մարտական ռոբոտն ես։ Նայիր շուրջդ մկնիկով և քայլիր՝ WASD։",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Ջեթփեք. սեղմիր Shift՝ ցատկ, պահիր Shift՝ թռիչք։ Էներգիան վերականգնվում է գետնի վրա։",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Կրակիր՝ ձախ կոճակ։ Նշանառություն՝ աջ կոճակ. ավելի ճշգրիտ է և մոտեցումով։ Մի քանի կրակոց արա։",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Վերալիցքավորում՝ R։ Փամփուշտներն ամենաուժեղը խփում են միջին հեռավորությունից՝ 20–50 մետր։",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Հրթիռ՝ Q։ Տանկերի և շենքերի դեմ։ Արձակիր հրթիռ։",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Վերևում ստրատեգի հրամանն է։ Վազիր կանաչ սլաքներով. երթուղու վրա արագ կվազես։ Գրավիր կետը՝ կանգնիր փարոսի մոտ։",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Քո ջոկատը ծածկում է քեզ. ձախից նրանց դիմանկարներն ու առողջությունն են։ Եթե ջոկատը հետ մնա, զինվորները կխնդրեն սպասել։",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — զինվորի արագ փոխարկում առանց մարտից դուրս գալու. ցատկ դեպի ջոկատ կամ տանկ, որը ամենամոտն է մարտին։ Փորձիր։",
"Next to a tank or turret press E to take control. Or just carry on.":"Տանկի կամ տուրելի կողքին սեղմիր E՝ դրանք կառավարելու համար։ Կամ պարզապես շարունակիր ճանապարհդ։",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Հիմա՝ ռազմավարությունը։ Սեղմիր «◩ Ռազմավարություն»՝ վերևում աջից. մարտադաշտի տեսքը վերևից։",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Հիմա՝ ռազմավարությունը։ Սեղմիր {0} (կամ «◩ Ռազմավարություն»՝ վերևում ձախից). մարտադաշտի տեսքը վերևից։",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Ստրատեգիայի ռեժիմում քեզ օգնում է Ուղեկիցը՝ վերևի պատուհանը ասում է՝ ինչ անել, շրջանակը ցույց է տալիս կոճակը, օղակը՝ տեղը քարտեզի վրա։ Կատարիր նրա երեք խորհուրդը։",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Ընտրիր ջոկատ և սեղմիր կանաչ «▶ Վերահսկել» կոճակը՝ նորից մարտում ես այդ զինվորի դեմքով։ Քանի դու կրակում ես, AI-ռազմավարը բանակը կառավարում է ինքնուրույն։",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Ընտրիր ջոկատ և սեղմիր {0} կամ կանաչ «▶ Վերահսկել»՝ նորից մարտում ես այդ զինվորի դեմքով (առանց ընտրության՝ քո սեփականով)։ Քանի դու կրակում ես, AI-ռազմավարը բանակը կառավարում է ինքնուրույն։",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Վարժանքն ավարտված է։ Գալան սկսում է հարձակումը։ Հաջողություն, զինվոր։",
