"No friendly vehicle or turret nearby":"Մոտակայքում սեփական տեխնիկա կամ աշտարակ չկա",
"You are driving {0}. {1} — back to infantry":"Դու կառավարում ես՝ {0}։ {1} — հետ հետևակ",
"You man the {0}. {1} — leave":"Դու {0}-ի մոտ ես։ {1} — դուրս գալ",
