"AI strategist on: builds the base and gives orders":"AI ռազմավարը միացված է՝ կառուցում է բազան և բաժանում խնդիրներ",
"AI strategist off — you are in command":"AI ռազմավարն անջատված է՝ հրամայում ես դու",
"Esc — menu · / — controls":"Esc — ընտրացանկ · / — կառավարում",
