"quick unit switch, staying in battle (Shift — back)":"զինվորի արագ փոխարկում՝ առանց մարտից դուրս գալու (Shift — հետ)",
"drop pod to the objective (Shift — into the fight)":"տեղափոխում կապսուլայով դեպի նպատակ (Shift — ուղիղ մարտի մեջ)",
"which objective the route leads to":"որ նպատակին է տանում ուղին",
