"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Հետո սեղմիր (հպիր) գետնին. գնում են և ճանապարհին կրակում։ Թշնամու վրա՝ հարձակվել նրա վրա։ Նույնն է, ինչ աջ կոճակը։",
