"Selected groups stay put and return fire.":"Ընտրվածները կանգնած են տեղում և պատասխան կրակ են բացում։",
"Retreat":"Նահանջել",
"Run back to the HQ (or nearest outpost) without engaging.":"Վազքով հետ դեպի շտաբ (կամ մոտակա առաջապահ դիրք)՝ մարտի չմտնելով։",
"Squads jet up through the dome portal and land at the enemy.":"Ջոկատները ռեակտիվ ուսապարկերով թռչում են գմբեթի պորտալով և վայրէջք կատարում թշնամու մոտ։",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Իրացնել ընտրված զինվորին, տանկին կամ տուրելը։ Նույն ստեղնը մարտում վերադարձնում է ռազմավարություն։",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 զինվոր՝ գրոհային, ծանր գնդացրորդ, հրթիռաձիգ, բժիշկ։",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"Ինքնավար մարտական մեքենա՝ թնդանոթ և գնդացիր, համազարկ, ծուխ, ձևակերպում։",
"Fast flying gunner, good against infantry.":"Արագ թռչող կրակող, լավ է հետևակի դեմ։",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"Էլիտար ջոկատ հզոր ռեակտիվ ուսապարկերով՝ կարող է վայրէջք կատարել գմբեթի միջով։",
"A lone railgun sniper.":"Միայնակ դիպուկահար ռելսոտրոնով։",
"Fast scout: sees far and spots enemies.":"Արագ հետախույզ՝ հեռու է տեսնում և լուսավորում թշնամիներին։",
"A squad drops from orbit right at the front line.":"Ջոկատն ուղեծրից իջնում է հենց առաջնագծի մոտ։",
"Jetpacks II: infantry reaches the dome and can sky-assault.":"Ռեակտիվ ուսապարկեր II՝ հետևակը հասնում է գմբեթին և կարող է վայրէջք կատարել։",
