"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Հանքաքարի նոր տեսք. երակները փայլուն զմրուխտե հղկված բյուրեղներ են սև բազալտի վրա՝ կայծերով և կանաչ մշուշով; էքստրակտորը վեցանկյուն պատվանդան է՝ մեղրաճաղի գմբեթով և ցանցավոր աշտարակով՝ կանաչ փարոս-կրակով (շերտը և դրոշակը՝ թիմի գույնով)",
