"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Նախընտրած դասը, ինչպես Battlefield-ում (U, թվեր զոհվելուց հետո). հայտնվում ես հենց դրանով, երբ հասանելի է",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Տեխնիկան առաջին դեմքով (V — դրսից/խցիկից); թեթև ավտոնպատակադրում՝ Կարգավորումներում",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Կորիզից այժմ հեշտ է դուրս գալ. Բացատ — դեպի հորան, B — պարկուճ մակերևույթ; կարողությունների էֆեկտները զրոյանում են զոհվելիս",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Անվերջ զարգացում. գեներալներ և Մարշալ ★, կարիերայի մակարդակներ, զինատեսակների վարպետություն և կցորդներ, մեդալներ, օրական պայմանագրեր — «Կարիերա» էկրան",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Ռազմավարություն. սահուն զում անիվով, պատկերակներ և ստորագրություններ միավորների վերևում (Alt — բոլորը), «Զորք / Շենքեր» վահանակը ձախից",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"RMB — շարժվել և կռվել ճանապարհին, կրկնակի RMB — արշավ՝ շարժվելով կրակելով; հազվադեպ հրամանները՝ «Ավելի շատ հրամաններ ▾»-ում; կոճակները չեն կրկնվում",
"New in v6":"Նորություն v6-ում",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Կրակոց՝ ինչպես շուտերներում. ակնթարթային փամփուշտներ, ավտոմատ 720 կրակոց/րոպե, գնդացիր, հետհրում, նպատակակետ RMB-ով, պահունակներ և R վերալիցքավորում, հարվածի նշաններ",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Ավելի ծանր ձգողություն, արագ արձագանքող ռեակտիվ պայուսակ, ցայտ Z-ով կամ կրկնակի պայուսակ օդում; մյուս ստորաբաժանում տեղափոխվելիս զենքն այլևս չի թռչում հետևից",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Ինժեներներ. նշիր ինժեներին, ընտրիր շենքը, դիր գծագիրը; էքստրակտորները՝ հանքաքարի երակների վրա; սեղմիր «ՀԱՆՔԱՔԱՐ»՝ տեսնելու եկամտի աղբյուրները և ինչպես արագացնել",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Մոխրագույն կոճակները կարելի է սեղմել՝ կցուցադրենք պատճառը և լուծման կոճակը; խոշոր կոճակներ, «Ընթացքում է» շերտ, «▶ Վերահսկել», Tab — մեկ ստեղն",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Ռազմավարության տեսախցիկը՝ առանց ցնցումների և շրջվելու, զում դեպի կուրսոր, մինի-քարտեզը կարելի է քաշել",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Նոր տեխնիկա. «Շնագայլ» ռեյդեր, «Գրադ» ՌՀԱՀ (ինքնանպատակակետ հրթիռներ), «Մուրճ» ականանետ; Երամը ստանում է «Իշամեղու», «Փեթակ», «Պարսատիկ»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Ռազմավարը չի փոխում հրամանները և չի սպամում ձայնով; մարտերը՝ քո կողքին; B — տեղափոխում, Shift+B — մարտի հորձանուտ; կողմնացույց, H — ո՞ր թիրախը",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Գործողությունների ազատություն (K) և «գործում եմ միայնակ» (J), F2 — կաղապարներ; Esc — դադար և հետ; պահպանումներ՝ սլոթեր, ֆայլի արտահանում և ներմուծում",
"New in v5.3":"Նորություն v5.3-ում",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Թռիչք. երկնաքարից հեռու ձգողությունն ավելի ուժեղ է, C օդում — արգելակ, մղումն ավելի կտրուկ է ղեկավարում; պորտալում այլևս չես «կախվում»",
"New in v5":"Նորություն v5-ում",
"Endless war by default and battle scale: normal, large, epic":"Անվերջ մարտ՝ լռելյայն, և մարտերի մասշտաբ. սովորական, խոշոր, էպիկական",
"Save and load the battle (autosave every 3 minutes)":"Մարտի պահպանում և բեռնում (և ավտոպահպանում ամեն 3 րոպեն մեկ)",
"Squadmates with callsigns: portraits, health and live chatter":"Ջոկատ՝ կանչանուններով. դիմանկարներ, առողջություն և կենդանի խոսակցություններ",
"Fog of war in strategy, friends and foes outlined differently":"Պատերազմի մառախուղ ռազմավարության մեջ, ընկերներն ու թշնամիները տարբեր ուրվագծված",
"Camera fly-over when switching, portal aurora instead of rings":"Տեսախցիկի թռիչք փոխարկելիս, պորտալի փայլ օղակների փոխարեն",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Կողմնակի խնդիրներ, կարճ ճանապարհ երկնքով, առաջին արշավախմբի մոդուլներ պաշարներով, բյուրեղներ, սառույց խառնարաններում, փոշու փոթորիկներ",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Վարժանք, կինո-ռեժիմ՝ տեսանյութերի ձայնագրությամբ, ուղեկցող տեխնիկա AI-ռազմավարից",
