"Mouse: LMB — fire, RMB — aim, Shift — jetpack. Tank: LMB — cannon, RMB — MG. M — sound, O — quality, Esc — menu.":"Մկնիկ՝ ձախ կոճակ — կրակ, աջ կոճակ — նպատակակետ, Shift — ռեակտիվ պայուսակ։ Տանկ՝ ձախ կոճակ — թնդանոթ, աջ կոճակ — գնդացիր։ M — ձայն, O — որակ, Esc — մենյու։",
