"SIGNAL TRANSFER":"ԱՋԴԱՆՇԱՆԻ ՓՈԽԱՆՑՈՒՄ",
"low ammo":"քիչ փամփուշտ",
"EMPTY — {0}":"ԴԱՏԱՐԿ — {0}",
"Simple fire: aim at an enemy and it fires. ◎ — aim, ⟳ — reload":"Պարզ կրակ. նպատակակետը թշնամու վրա՝ կրակում է ինքնուրույն։ ◎ — նպատակակետ, ⟳ — վերալիցքավորում",
"● — fire, ◎ — aim, ⟳ — reload":"● — կրակ, ◎ — նպատակակետ, ⟳ — վերալիցքավորում",
"◎ — aim, R — reload, » — jet dash":"◎ — նպատակակետ, R — վերալիցքավորում, » — թռիչք պայուսակով",
"RMB — aim · {0} — reload · {1} standing — crouch · {2} or 2×{3} in the air — dash":"RMB — նպատակակետ · {0} — վերալիցքավորում · {1} կանգնած — կքվել · {2} կամ 2×{3} օդում — թռիչք",
"Track another objective":"Հետևել այլ թիրախի",
"Orders ↔ free play":"Հրամաններ ↔ գործողությունների ազատություն",
"Squad with me ↔ going solo":"Ջոկատը ինձ հետ ↔ գործում եմ միայնակ",
"Redeploy: pod to objective / into the fight":"Տեղափոխում. պարկուճ թիրախի մոտ / մարտի հորձանուտ",
"The objective is far. {0} — drop pod straight to it (with your squad). Shift+{1} — possess a trooper in the thick of the fight.":"Թիրախը հեռու է։ {0} — տեղափոխում պարկուճով անմիջապես թիրախի մոտ (ջոկատի հետ)։ Shift+{1} — վերահսկել զինվորին մարտի հորձանուտում։",
"Intel: a Swarm squad is heading your way — {0}, about {1} meters.":"Հետախուզություն. Swarm-ի ջոկատը գալիս է ձեր կողմը՝ {0}, մոտ {1} մետր։",
"Contact from above! A Swarm pod is coming down {0}, {1} meters!":"Շփում վերևից։ Swarm-ի պարկուճը իջնում է՝ {0}, {1} մետր։",
"Swarm signaller {0}! It will call a drop in 12 seconds — kill it first!":"Swarm-ի ազդանշանիչ {0}։ 12 վայրկյանից կկանչի դեսանտ՝ նախ ոչնչացրու նրան։",
"Signaller down — no drop.":"Ազդանշանիչը խոցված է՝ դեսանտ չի լինի։",
"The signaller got it off! Swarm pod inbound.":"Ազդանշանիչը հասցրեց։ Swarm-ի պարկուճը մոտենում է։",
"The Swarm is counter-attacking {0}! Get ready to defend.":"Swarm-ը հակահարձակման է անցնում՝ {0}։ Պատրաստվեք պաշտպանության։",
"You're going solo. {0} returns to the strategist. {1} — call them back.":"Դու գործում ես միայնակ։ {0}-ը անցնում է ռազմավարի հրամանատարության տակ։ {1} — հետ կանչել։",
"No free squads nearby — you stay solo for now.":"Մոտակայքում ազատ ջոկատներ չկան՝ առայժմ դու միայնակ ես։",
"{0}: on our way to you, commander!":"{0}. գալիս ենք քեզ մոտ, հրամանատար։",
