"Saves live only in this browser on this device (localStorage). Anyone else who downloads the game gets none of your saves. To move a battle to another computer or browser: \"Export to file\" here → \"Import from file\" there. Autosave runs every 3 minutes of battle and when you quit to the menu.":"Պահպանումները պահվում են միայն այս բրաուզերում, այս սարքի վրա (localStorage)։ Եթե ուրիշը ներբեռնի խաղը, քո պահպանումները նրա մոտ չեն լինի։ Մարտը մեկ այլ համակարգիչ կամ բրաուզեր տեղափոխելու համար՝ այստեղ «Արտահանել ֆայլի» → այնտեղ «Ներմուծել ֆայլից»։ Ավտոպահպանումը՝ ամեն 3 րոպե մարտը և մենյու դուրս գալիս։",
