"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Նռնակ. պահիր G — կտեսնես աղեղը և պայթյունի շրջանը; քաշիր մատդ կոճակի վրա՝ անկյուն; բաց թող՝ նետում։",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Նռնակ. պահիր {0} — աղեղ և պայթյունի շրջան, բաց թող՝ նետում։ Հեռավորությունը՝ հայացքի անկյամբ, անիվ — ուժ, RMB — ներքևից նետում։",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Նռնակներ. պահիր G — թռիչքի աղեղ, պայթյունի կետ և շրջան, հեռավորություն; բաց թող՝ նետում։ Հեռավորությունը՝ հայացքի անկյամբ, անիվ — ուժ, RMB — ներքևից նետում",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Նռնակը ետ է թռչում և գլորվում թեք մակերեսով, պայթյուն 2.5 վ հետո; 2 նռնակ, վերականգնում 9 վ; նշան-զգուշացում մոտակայքում թշնամու նռնակի մասին",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Նռնակ. պահել — աղեղ և պայթյունի կետ, բաց թողնել — նետում · տանկի ֆորսաժ",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — պահիր՝ երևում է աղեղը և պայթյունի շրջանը, բաց թող՝ նետում։ Պայթյուն 2.5 վ հետո, 2 նռնակ։",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Նռնակ ({0}). պահիր — թռիչքի աղեղ, պայթյունի կետ և շրջան, հեռավորություն; բաց թող՝ նետում; կարճ սեղմում՝ անմիջապես նետում։ Հեռավորությունը՝ հայացքի անկյամբ, անիվ — ուժ, RMB — ներքևից նետում։ Հեռախոս. պահիր G և քաշիր մատդ։",
