"Each level costs more than the last; every 50 levels — \"Veteran ★\". XP comes from everything: combat, orders, medals, contracts.":"Յուրաքանչյուր մակարդակ նախորդից թանկ է. ամեն 50 մակարդակը՝ «Վետերան ★»։ Փորձ տրվում է ամեն ինչի համար՝ մարտ, հրամաններ, մեդալներ, պայմանագրեր։",
