"Developer mode (sandbox)":"Մշակողի ռեժիմ (պոլիգոն)",
"all unlocked · career untouched":"ամեն ինչ բաց է · կարիերան չի փոխվում",
"Developer mode":"Մշակողի ռեժիմ",
