"Builder selected — pick a building on the right and tap a spot":"Ինժեները ընտրված է՝ աջից ընտրիր շենքը և հպիր տեղին",
"Camera follows the selection":"Տեսախցիկը հետևում է ընտրվածներին",
"swipe up — at the target":"սահեցում վերև՝ թիրախին",
"No target locked":"Շրջանակում թիրախ չկա",
"Swipe on the right — look":"Աջից սահեցում՝ հայացք",
"Hold — fly":"Պահիր՝ թռիչք",
"AUTO — target lock":"ԱՎՏՈ՝ թիրախի գրավում",
"Tap the frame — rocket":"Հպիր շրջանակին՝ հրթիռ",
"Swipe up — grenade at target":"Սահեցում վերև՝ նռնակ թիրախին",
"Pinch — grenade / rocket / zoom":"Սեղմում՝ նռնակ / հրթիռ / մոտեցում",
"Double tap right — reflex":"Աջից 2× հպում՝ ռեֆլեքս",
"Tap — select, tap again — order":"Հպում՝ ընտրել, էլի հպում՝ հրաման",
"Hold — command menu, hold and drag — box":"Պահիր՝ հրամանների ցանկ, պահիր և քաշիր՝ շրջանակ",
"Pinch — zoom, twist — rotate":"Սեղմում՝ մասշտաբ, երկու մատով պտույտ՝ պտտել",
"Show / hide the secondary HUD":"Ցույց տալ / թաքցնել երկրորդական HUD-ը",
"Minimap: show / hide (tap the map to jump there)":"Նվազ քարտեզ՝ ցույց տալ / փակել (հպիր քարտեզին՝ տեսախցիկը այնտեղ)",
"Tap a point for the ability":"Հպիր կետին՝ կարողության համար",
