"SNIPER SEES YOU":"ԴԻՊՈՒԿԱՀԱՐԸ ՔԵԶ ՏԵՍՆՈՒՄ Է",
"CAN'T SEE YOU":"ՉԻ ՏԵՍՆՈՒՄ",
