"Well done!":"Հիանալի՜",
"Step":"Քայլ",
"Repeat step":"Կրկնել քայլը",
"Press \"Resume\" to get back to the training.":"Սեղմիր «Շարունակել»՝ վարժանքին վերադառնալու համար։",
"First go back: ":"Սկզբում վերադարձիր՝ ",
"⌫ — repeat step · Esc — pause":"⌫ — կրկնել քայլը · Esc — դադար",
"Look around":"Տեսք",
"Movement":"Շարժում",
"Jetpack":"Ռեակտիվ պայուսակ",
"Air brake":"Արգելակ օդում",
