"· basic{0}":"· հիմնական{0}",
"· advanced":"· առաջադեմ",
"· rare":"· հազվագյուտ",
"Advanced: class order":"Ընդլայնված՝ դասերի հերթականությունը",
"Voice of hints and curator":"Հուշումների և Ուղեկցի ձայնը",
"Advanced: custom class order":"Ընդլայնված՝ դասերի սեփական հերթականություն",
"Voice of hints & curator":"Հուշումների և Ուղեկցի ձայնը",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Հեռախոս՝ ջոյստիկների երեք ռեժիմ։ Միայն ձախը՝ «ավտո» (ուժեղ մագնիս, բայց թույլ փամփուշտներ)։ Միայն աջը՝ նշանն ինքնուրույն է միանում, մագնիսն ուժեղ է, կրակն ավելի ճշգրիտ։ Երկուսը միասին՝ առանց նշանի, մագնիսն ու ճշգրտությունը պակաս են։ Աջ կողմի 👁 կոճակը թաքցնում/վերադարձնում է ինտերֆեյսը։",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Հեռախոս՝ ռազմավարությունը պարզեցված է՝ միայն ինժեներ և շենքեր։ Ձախից քարտեր (ինժեներ, Շտաբ, Զորանոց…)՝ հպում, տեսախցիկը թռչում է այնտեղ, ներքևում անմիջապես երևում է՝ ինչ կառուցել/արտադրել։ «Մարտի» — վերևից ձախ։ Բանակը կռվում է ինքնուրույն։ Ամբողջական ռազմավարություն՝ Կարգավորումներ → Հեռախոս։",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Վերահսկում՝ երկու նշիչ՝ «Ջոկատներ» և «Տեխնիկա» (հեռախոսում տեխնիկան լռելյայն անջատված է՝ այն վարում է AI-ն)։ Եթե տեխնիկան անջատված է, E (հեռախոսում՝ աջ կոճակը) բարեկամական մեքենայի մոտ՝ նստել նրա թնդանոթի մոտ․ մեքենան գնում է ինքնուրույն, դու կրակում ես։ Հին «դասերի սեփական հերթականությունը»՝ «Ընդլայնվածում»։ Վերահսկելիս յունիտը պատասխանում է ռադիոյով։",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Խելացի հուշումներ՝ հիմնականները ինքնուրույն անջատվում են 2-րդ գործարկումից հետո, բայց խաղը կհուշի այն գործառույթը, որից դու այդպես էլ չես օգտվել։ Նշիչներ՝ հիմնական / առաջադեմ / հազվագյուտ, առանձին՝ հուշումների և Ուղեկցի ձայնը։",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Ռեֆլեքսը լիցքավորվում է սպանություններից (շարքը՝ ավելի ուժեղ)։ Զինակիցները հետ են մնացել կամ զոհվել են՝ ռազմավարը վայրէջք է կատարում նորերին քեզ մոտ (սովորական համալրումից թանկ)։ v7.2gfx գրաֆիկան և ձայնը ներառված են՝ ամպերով պայթյուններ, ծուխ, բեկորներ, հանքահորերի և խառնարանների ակուստիկա։ Կառուցման ամսաթիվն արդեն իրական է։",
