"Follow the strategist's orders — XP for them is doubled and tripled.":"Կատարիր ռազմավար-AI-ի հրամանները՝ դրանց համար փորձը կրկնապատկվում և եռապատկվում է։",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — ակնթարթորեն անցնել մարտին ամենամոտ ջոկատին կամ մեքենային։",
"Bullets hit hardest at medium range, 20–50 meters.":"Փամփուշտներն ամենաուժեղն են հարվածում միջին հեռավորությունից՝ 20–50 մետր։",
