"DEVELOPER":"ՄՇԱԿՈՂ",
"Developer: mode, arsenal, range":"Մշակող՝ ռեժիմ, զինանոց, պոլիգոն",
"sandbox · all trainings · cinema":"պոլիգոն · բոլոր վարժանքները · կինո",
"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Կարիերան և պահպանումները չեն փոխվում։ Մարտում նույն ցանկը «🛠 Ցանկ» կոճակն է վերևից աջ{0}։",
"New developer match":"Մշակողի նոր խաղ",
"all unlocked, endless ore, instant build, arsenal":"ամեն ինչ բաց է, անվերջ հանքաքար, ակնթարթային շինարարություն, զինանոց",
"Trainings — all 4":"Վարժանքներ — բոլոր 4-ը",
"PC and phone (strategy and shooter)":"ՀՀ և հեռախոս (ռազմավարություն և կրակող)",
"Cinema: split screen":"Կինո՝ բաժանված էկրան",
"strategist bot left, shooter bot right":"ձախից՝ ռազմավար-բոտ, աջից՝ կրակող-բոտ",
"Cinema: everything built":"Կինո՝ ամեն ինչ կառուցված է",
"both bases built and upgraded — for footage":"երկու բազաները կառուցված և կատարելագործված են՝ նկարահանման համար",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Կինո ռեժիմ՝ բաժանված էկրան․ ձախից ռազմավար-բոտ (բազայի և բանակի տեսք վերևից), աջից կրակող-բոտ առաջին դեմքով։ Կոճակները ներքևում (և S, P ստեղները)՝ «Բաժանված էկրան» և «★ Ամեն ինչ կառուցված է» — երկու բազաները կառուցված և կատարելագործված են նկարահանման համար։",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Միջուկն ու երկնաքարի միջով անցնող թունելներն այլևս չկան. երկնաքարը ամբողջական է, մարտը միայն մակերևույթին է։",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Հեռախոս. 👁 թաքցնում է ինտերֆեյսը, բայց թողնում է ջեթպակը, ⇆-ը, ստիկերը և խնդրի նշանը։ «◎ Նշանառություն» (միայն աջ մատով) — ակնհայտորեն ավելի ուժեղ ու լայն մագնիս. երեք ռեժիմների մագնիսի ուժը՝ Կարգավորումներ → Կառավարում → «Ընդլայնված»։ Մեքենայի թնդանոթի մոտ կոճակը կոչվում է «Իջնել»։",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Վարժանք. հեռախոսում՝ միայն հեռախոսային, համակարգչում՝ միայն համակարգչային։ Բոլոր 4-ը «🛠 Մշակող» ընտրացանկում են։ Մշակողի ռեժիմն ու Զինանոցը միավորված են մեկ ընտրացանկում (մարտում՝ «🛠 Ընտրացանկ» վերևում աջից, համակարգչում նաև F8)։",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Գրաֆիկայի «Dendy (8-բիթ)» և «16-բիթ» ոճերը՝ Կարգավորումներ → Գրաֆիկա → «Գրաֆիկայի ոճ» (մանրամասները՝ ⚙ կոճակը)։ Եթե խաղի առաջին ~10 վրկ-ում FPS-ը 24-ից ցածր է, Dendy-ն ինքնուրույն միանում է (20-ից ցածր՝ էլ ավելի խոշոր պիքսել, 120 տող). վերևի «վերադարձնել սովորականը» ազդանշանը սովորական գրաֆիկան վերականգնում է ընդմիշտ։ Ընտրացանկում քո ընտրությունը միշտ գերակա է։",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Շրջակայքի 3D մոդելներ (ավերակներ, տեխնիկա, ամրություններ)՝ միայն լավ գնահատված, բեռնվում են ըստ պահանջի։ Անջատել՝ Կարգավորումներ → Գրաֆիկա → «Շրջակայքի նոր 3D մոդելներ»։",
"New in v7.5":"Նորություններ v7.5-ում",
"NEW IN v7.5":"ՆՈՐՈՒԹՅՈՒՆՆԵՐ v7.5-ՈՒՄ",
