"Trooper, the engineers are busy — help finish the {0}, {1} m. {2} at the site.":"Մարտիկ, ինժեներները զբաղված են՝ օգնիր ավարտել. {0}, {1} մ։ {2}՝ շինարարության մոտ։",
"Strategist order: finish the {0} ({1} m)":"Ռազմավարի հրաման՝ ավարտել {0}-ը ({1} մ)",
"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"Ռազմավար. ⌖ նշան թշնամու կուտակման վրա, {0} մ — հրետանային հարված 8 վայրկյանից։ Մի մոտեցիր։",
"MLRS \"Grad\" ×{0}: salvo at the strategist's mark":"ԻՀՕՀ «Գրադ» ×{0}՝ համազարկ ռազմավարի նշանով",
"a heavy MG for 90 s":"ծանր գնդացիր՝ 90 վրկ",
"incendiary rounds for 60 s":"դյուրավառ փամփուշտներ՝ 60 վրկ",
"3 rockets with no cooldown":"3 հրթիռ առանց վերալիցքավորման",
