"⌖ ARTILLERY":"⌖ ՀՐԵՏԱՆԱՅԻՆ ՀԱՐՎԱԾ",
"STRATEGIST'S MARK":"ՌԱԶՄԱՎԱՐԻ ՆՇԱՆ",
"BUILD SITE":"ՇԻՆԱՐԱՐՈՒԹՅՈՒՆ",
"cache":"պահոց",
