"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Շինարարություն զինվորներով. E (հեռախոսում՝ «Մտնել») սեփական շինարարության մոտ — զինվորը ինքը կառուցում է, կողքի ընկերները օգնում են։ Եթե ինժեներները զբաղված են, ռազմավարն ինքը կխնդրի օգնել՝ «ՇԻՆԱՐԱՐՈՒԹՅՈՒՆ» նշանով։",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Ռազմավարի նշաններ. ռազմավարը ⌖ է դնում քո մոտ գտնվող թշնամու կուտակման վրա — 8 վրկ հետո այնտեղ հրետանի է խփում, իսկ մոտակա սեփական ԻՀՕՀ «Գրադները» համազարկ են տալիս։ Քո սեփական հրետանային հարվածը ռազմավարական ռեժիմից նույնպես «Գրադների» աջակցությամբ է։",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Զենքի պահոցներ բեռնարկղերում և ընկած արբանյակներում (📦 երևում է 70 մ-ից). E — ծանր գնդացիր 90 վրկ, դյուրավառ փամփուշտներ կամ հրթիռներ, գումարած լիքը նռնակներ։ Սողալ. Ctrl — պառկել / վեր կենալ (ավելի ցածր, հանգիստ, ճշգրիտ, բայց դանդաղ)։",
"Anonymous statistics":"Անանուն վիճակագրություն",
"no names or emails: version, device, play time — to make the game better":"առանց անունների և փոստի՝ տարբերակ, սարք, խաղի ժամանակ — խաղը լավացնելու համար",
"Anonymous statistics (no names or emails)":"Անանուն վիճակագրություն (առանց անունների և փոստի)",
"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"Կինո-սպլիտսկրին, առանց միջուկի և թունելների, շինարարություն զինվորներով, ռազմավարի նշաններ, պահոցներ, սողալ, մշակողի ընտրացանկ",
"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Ստիկերի երեք ռեժիմ հեռախոսում, պարզ ռազմավարություն, մեքենայի թնդանոթ, կիրճերով ռելիեֆ, ջոկատների դասեր, պայթուցիկ",
"Lite mode, two-stick phone controls":"Թեթև ռեժիմ, երկու ստիկ հեռախոսում",
"Milestone: outposts and HQ upgrades, cinematic misses, knockdowns":"Հանգրվան. ֆորպոստեր և ՍՀ-ի բարելավումներ, կինոյային վրիպումներ, պայթյուններից ընկնել",
"Milestone: strategy + shooter in one game, v6 guns":"Հանգրվան. ռազմավարություն + շուտեր մեկ խաղում, v6 զենքեր",
"Milestone: base, squads, vehicles":"Հանգրվան. բազա, ջոկատներ, տեխնիկա",
"Milestone: first armies and strategy":"Հանգրվան. առաջին բանակները և ռազմավարությունը",
"Milestone: bigger meteor, raymarcher":"Հանգրվան. ավելի մեծ երկնաքար, ռեյմարչեր",
"Milestone: jetpack, gravity, explorers":"Հանգրվան. ռանեց, ձգողություն, հետազոտողներ",
"The very first: a meteor inside the portal sky":"Ամենաառաջինը՝ երկնաքար պորտալ-երկնքի ներսում",
"Old versions are only in the itch build":"Հին տարբերակները կան միայն խաղի itch-արխիվում",
"new":"նոր",
"milestone":"հանգրվան",
"this one":"այս",
"MB":"ՄԲ",
"GAME VERSION":"ԽԱՂԻ ՏԱՐԲԵՐԱԿ",
"Do not like the new version — play the one you are used to. The choice is remembered; every version has its own saves and settings (these stay safe). An old version is loaded only when chosen.":"Նոր տարբերակը դուր չի գալիս՝ խաղա սովորականով։ Ընտրությունը հիշվում է. յուրաքանչյուր տարբերակ ունի իր պահպանումներն ու կարգավորումները (դրանք չեն կորչի)։ Հին տարբերակը բեռնվում է միայն ընտրելիս։",
"No archive here — old versions are available in the itch.io build.":"Այստեղ արխիվ չկա՝ հին տարբերակները հասանելի են itch.io-ի խաղում։",
"Latest":"Վերջինները",
