"Swarm":"Գալա",
"Assault tank \"Rhino\"":"«Ռնգեղջյուր» գրոհային տանկ",
"Consortium. Super-heavy tank: 2300 hull, cannon +45% damage, slow.":"Կոնսորցիում։ Գերծանր տանկ՝ 2300 ամրություն, թնդանոթ +45 % վնաս, դանդաղ։",
