"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ Խաղալ հիմա» — ընտրացանկի առաջին կոճակը՝ կարճ թռիչք պորտալ-երկնքի տակ և միանգամից մարտ (բաց թողնել՝ ցանկացած ստեղն կամ հպում)։",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Հարվածները զգացվում են. մետաղական ձայն և կայծեր, սպանության նշան նշանառության մոտ (գլխին՝ դեղին), ×N շարք, պայթյուններից սահուն ցնցում, slow-mo կարևոր սպանությունների ժամանակ։ Ցնցումը, slow-mo-ն և հուշումը կարելի է անջատել Կարգավորումներում։",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Խաղի արդյունք. ժամանակ, ոչնչացումներ, լավագույն շարք, ★ MVP և լավագույն ջոկատ, խաղի քարտ — «⇪ Կիսվել», PNG կամ խաղի հղում։",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"«Ինչ անել հիմա» հուշումը ձախից՝ ռեսուրսների տակ. ռազմավարի հրաման, գրավման կետ, Figure-ի հարձակում։ ✕ կամ F7 — ծալել։",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Մարտը պահպանվում է ինքնուրույն, եթե փակես կամ ծալես ներդիրը — ընտրացանկում «⟲ Շարունակել»։",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 տարբերակը մնացել է «🕘 Խաղի տարբերակ» ընտրացանկում՝ եթե նորը դուր չգա։ Անանուն վիճակագրությունն (առանց անունների և փոստի) այժմ ուղարկվում է. անջատել՝ Կարգավորումներում։",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«Խաղալ հիմա», հարվածների արձագանք, խաղի արդյունք քարտով, «ինչ անել» հուշում, ավտոպահպանում",
"and older: v7.5, v7.4, milestones v1–v7.0":"և հները՝ v7.5, v7.4, հանգրվաններ v1–v7.0",
"New in v7.6":"Նորություններ v7.6-ում",
"NEW IN v7.6":"ՆՈՐՈՒԹՅՈՒՆՆԵՐ v7.6-ՈՒՄ",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Խմբակցության ընտրություն խաղից առաջ՝ «Կոնսորցիում» (ծանր հետևակ ուժային զրահով, զրահ և հրետանի) կամ «Գալա» (արագություն, դրոնների երամներ, ծանր կրակոցներ աղավաղմամբ)։ AI-ն խաղում է մյուսի համար։ Ընտրությունը հիշվում է։",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Յուրաքանչյուր խմբակցություն ունի իր տեխնիկան և յուրահատուկը. Կոնսորցիումը՝ «Ռնգեղջյուր» տանկ և «Կերամիտե թիթեղներ», Նխիրը՝ «Դրոնների երամ» և «Ֆազային ջեթփաքեր»։ Հավասարակշռությունը ստուգվել է բոտերի խաղերով։",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Պայթյունների խառնարաններ. հրետանին, հրթիռները և տանկերի թնդանոթները փոսեր են փորում երկնաքարի մեջ. դրանցով կարելի է քայլել և վարել, դրանցում կարելի է թաքնվել։",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Երրորդ դեմքի տեսք զինվորի համար (V, հիշվում է. հեռախոսում՝ Կառավարում) և տեխնիկայի սահուն տեսախցիկ՝ նշանով, թե որտեղ կընկնի թնդանոթի արկը։",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 տարբերակը մնացել է «🕘 Խաղի տարբերակ» ընտրացանկում, եթե նորը դուր չգա։",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Կոնսորցիում / Նխիր խմբակցություններ՝ խաղից առաջ ընտրությամբ, պայթյունների խառնարաններ, երրորդ դեմքի տեսք",
"and older: v7.6, v7.5, milestones v1–v7.0":"և ավելի հին՝ v7.6, v7.5, v1–v7.0 հանգրվաններ",
