"looking for an enemy zone":"փնտրում եմ թշնամու գոտի",
"LMB — strike (hold — heavy) · RMB — block · Shift — blink · Q — shurikens · G — teleport":"Ձախ կոճակ — հարված (պահիր — ծանր) · աջ կոճակ — արգելափակում · Shift — արագ թռիչք · Q — շուրիկեններ · G — տելեպորտ",
"Block":"Արգելափակում",
"Blink":"Թռիչք",
"Shurikens":"Շուրիկեններ",
"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor ռադիո. EDMITRY-ի 100+ կատարում հենց խաղում՝ 📻 կոճակը (համակարգչում՝ 5 ստեղն, [ ] — կատարում)։ Երաժշտությունը բեռնվում է ըստ պահանջի և խաղը չի ծանրացնում. ձայնը և ավտոմեկնարկը՝ Կարգավորումներում, կա նաև «Լսել Spotify-ում» հղում։",
"tuning…":"կարգավորում…",
"on air · cockpit":"եթեր · խցիկ",
"on air":"եթերում",
"paused":"դադար",
"no signal — silent":"կապ չկա — լուռ է",
"tap ▶":"սեղմիր ▶",
"RADIO PORTAL METEOR":"PORTAL METEOR ՌԱԴԻՈ",
"Now playing":"Հիմա հնչում է",
"Listen on Spotify":"Լսել Spotify-ում",
"RADIO":"ՌԱԴԻՈ",
"on/off":"միաց.",
"track":"կատարում",
"Radio":"Ռադիո",
"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"Portal Meteor ռադիո միաց./անջ. ([ ] — կատարում, Shift+[ ] — ձայն)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 աջում՝ Portal Meteor ռադիո. EDMITRY-ի երաժշտությունը մարտի ընթացքում։",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Portal Meteor ռադիո. EDMITRY-ի երաժշտությունը մարտի ընթացքում։ [ ] — կատարում։",
"Radio Portal Meteor (EDMITRY): volume":"Portal Meteor ռադիո (EDMITRY). ձայն",
"Radio: start by itself in battle":"Ռադիո՝ մարտում ինքնուրույն միանա",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Ռոբո-նինջա. կատանայով կիբորգ։ Բացվում է Զորանոցում «Ստվերի արձանագրություն» հետազոտությամբ (պետք է Մեխերի գործարան)։ Ինքն է տելեպորտվում թշնամու գոտիներ, մասերի է բաժանում թշնամիներին (առանց արյան՝ կայծեր), թռիչքներ է կատարում, շուրիկեններ, մենամարտեր թշնամու նինջայի հետ։ Վերցրու նրա կառավարումը՝ ԱՎՏՈ ռեժիմ կամ ձեռքով կառավարում (հեռախոսում՝ իր կոճակները)։",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor ռադիո. EDMITRY-ի 103 կատարում հենց խաղում։ 5 ստեղնը (վերանշանակվում է), հեռախոսում՝ ☰ → Կարգավորումներ → Ձայն։ Ձայնը և «մարտում ինքնուրույն միանա»-ն՝ կարգավորումներում. երաժշտությունը խլանում է պայթյունների և ռադիոյի ձայնի տակ։",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Նոր լեզուներ՝ ուզբեկերեն և տաջիկերեն՝ ամբողջությամբ. չինարեն, իսպաներեն, պորտուգալերեն՝ մասամբ։ Լեզվի նոր ընտրիչը մենյուում՝ «Նոր խաղ»-ի կողքին։",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Հեռախոս. «թաքցնել պատկերակները» 👁 մնացած կոճակները հավաքում է կոկիկ սյունակում աջ եզրին. դիմանկարային դիրքում այլևս չի համընկնում. iPhone՝ խաղը չի հակասում Safari-ի ժեստերին, իսկ «Կիսվել → Տան էկրան» այն բացում է լիաէկրան։",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1-ից՝ ☰ մենյու անկյունում (դադար, նորից, վարժանք, գրաֆիկա), առանց ավտո-Dendy-ի, ✋ գործողության կոճակ հեռախոսում։ v7.8.1-ը և v7.8-ը մնացել են «🕘 Խաղի տարբերակ» մենյուում։",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Ռոբո-նինջա, EDMITRY ռադիո, ուզբեկերեն և տաջիկերեն, հեռախոսի և iPhone-ի հարմարավետություն",
"and older: v7.8.1, v7.8, milestones v1–v7.0":"և հին տարբերակներ՝ v7.8.1, v7.8, v1–v7.0 հանգրվաններ",
