"Napalm":"Նապալմ",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"12 մ կրակի գոտին այրվում է 9 վայրկյան՝ ժամանակի ընթացքում վնաս, ճնշում, ծուխ։ 2.5 վ հետո։ Վառում է մեթանը։",
"Bomber: target received, inbound!":"Ռմբակոծիչ՝ թիրախն ընդունված է, մոտենում ենք։",
"Attack jet: napalm inbound!":"Գրոհիչ՝ նապալմը ճանապարհին է։",
"Support: crate, recon, \"Grad\", artillery, carpet bombing, napalm (then 1–6)":"Աջակցություն՝ արկղ, հետախուզություն, «Գրադ», հրետանային հարված, ռմբակոծություն, նապալմ (հետո 1–6)",
"☄ Meteor shower in 10 s — take cover: the rock hangar, under a ridge!":"☄ Երկնաքարային անձրև 10 վ հետո՝ թաքնվիր. ժայռերի անգարում, լեռնաշղթայի տակ։",
"Warning: meteor shower! Everyone take cover":"Ուշադրություն՝ երկնաքարային անձրև։ Բոլորը ապաստան",
"Meteor shower in ":"Երկնաքարային անձրև՝ ",
