"Living world: requests, hero quests, breakthrough ops":"Կենդանի աշխարհ՝ իրենցների խնդրանքներ, հերոսների քվեստներ, մարտի ուղղության փոփոխություն",
"Living world":"Կենդանի աշխարհ",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Քոնները օգնություն են խնդրում և պարգևատրում, հերոսները քվեստ են տալիս, ձգձգված ճակատը կոտրվում է օպերացիայով",
"A request":"Իրենցների խնդրանք",
"Breakthrough":"Մարտի ուղղության փոփոխություն",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Քոնները երբեմն օգնություն են խնդրում՝ ձայն ռադիոյով, «ԽՆԴՐԱՆՔ» քարտ և ✋ նշան։ Ջոկատին սեղմել են՝ ոչնչացրու նրա մոտ գտնվող թշնամիներին։ Պարգև՝ զինվոր պարկուճով բազայից, զենք բագիի թափքից, նշանառուի տեղ կամ ուղեծրային ծածկույթ։ Չես ուզում՝ ✕ կամ պարզապես անտեսիր։",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Վետերան հետախույզ «Բու»-ն քվեստ է առաջարկում։ Y — ընդունել (N — մերժել)։ Գնա ★ նշանի մոտ, հեռացրու պահակախումբը և կանգնիր օդաչուի մոտ 3 վրկ՝ նա կմիանա քո ջոկատին։",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Ճակատը կանգնել է՝ շտաբը մարտի ուղղության փոփոխություն է առաջարկում։ Y — ընդունել։ Պահիր ռելեն 8 վրկ առանց թշնամիների մոտակայքում՝ թշնամու քարտեզը տեսանելի է 60 վրկ։ Գեներատոր՝ թշնամու աշտարակները լռում են 2 րոպե։ Ռազմավարում՝ «Հանձնարարել ջոկատին»։ Թշնամին նույնպես կարող է. հետևիր ⚠-ին։",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Քոնները օգնություն են խնդրում՝ «ԽՆԴՐԱՆՔ» քարտ և ✋ նշան։ Ոչնչացրու սեղմված ջոկատի մոտ գտնվող թշնամիներին՝ պարգև կստանաս։ ✕ — բաց թողնել։",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Հերոս «Բու»-ն քվեստ է առաջարկում՝ հպիր «Ընդունել»։ Գնա ★-ի մոտ, հեռացրու պահակախումբը, կանգնիր օդաչուի մոտ։",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Ճակատը կանգնել է՝ հպիր «Ընդունել» և պահիր ռելեն 8 վրկ՝ թշնամու քարտեզը մեկ րոպեով կբացվի։",
"Pod redeploy from the base: {0} m — through the sky portal":"Տեղափոխում կապսուլայով բազայից՝ {0} մ՝ երկնային պորտալով",
"Pod away from the base! Hold on — exit over the target.":"Կապսուլան բազայից մեկնեց։ Դիմացիր՝ դուրս գալը թիրախի վրա է։",
"Landed at the objective!":"Վայրէջք թիրախի մոտ։",
"LAUNCH FROM BASE":"ՄԵԿՆԱՐԿ ԲԱԶԱՅԻՑ",
"LANDING":"ՎԱՅՐԷՋՔ",
"REDEPLOY":"ՏԵՂԱՓՈԽՈՒՄ",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Պողպատե Մազմզուկը կպել է՝ ուտում է զրահը −2/վրկ։ Կանգնիր 3 վրկ մարտից դուրս կամ գնա ճարտարագետի մոտ",
"An engineer brushed the fluff off":"Ինժեները մաքրեց թուխսը",
"The fluff fell off — armour is safe":"Թուխսը թափվեց՝ զրահը անվնաս է",
"The firefly swarm scattered by the blast":"Լուսատտիկների երամը ցրվեց պայթյունից",
