"Button remapping comes in a later version. Keyboard, mouse and touch work as before; hints switch to the gamepad by themselves while you use it.":"Կոճակների վերանշանակումը՝ հաջորդ տարբերակում։ Ստեղնաշարը, մկնիկն ու հպումը աշխատում են ինչպես առաջ․ հուշումները գեյմփադի վրա անցնում են ինքնուրույն, երբ օգտագործում ես այն։",
