"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Կառուցում է շենքեր և Էքստրակտորներ, վերանորոգում է, հանում է «Պողպատե Սերմնաբուրդը» մյուսներից։",
"A squad flies from the base launch pad through the sky portal right to the target.":"Ջոկատը թռչում է բազայի արձակման հարթակից երկնային պորտալով ուղիղ թիրախի մոտ։",
