"Members: ":"Կազմ՝ ",
"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Հիմնական մարտական տանկ՝ թնդանոթ և գնդացիր։ Կոնսորցիումի «Բուլդոգը» ամրագույն է, Երամի «Սարդը»՝ արագ։",
"Heavy tank":"Ծանր տանկ",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Ինքնավար թռչող կրակողը՝ արագ, փխրուն, վախենում է հակաօդային պաշտպանությունից։",
"Upgrade":"Կատարելագործում",
"Longer, faster jetpacks for all infantry.":"Ավելի հեռու և արագ ռեակտիվ պայուսակներ ամբողջ հետևակի համար։",
"Extractors mine more ore.":"Էքստրակտորներն ավելի շատ հանքաքար են արդյունահանում։",
"Army-wide levels: less damage taken / more damage dealt.":"Ամբողջ բանակի մակարդակներ՝ պակաս վնաս իրենց վրա / ավելի շատ վնաս թշնամուն։",
"Levels":"Մակարդակներ",
"Base":"Բազա",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Բազայի սիրտը՝ ջոկատներ, ինժեներներ, պարկուճներ, հետազոտություններ։ Շտաբի կորուստը՝ պարտություն։",
"Produces: ":"Արտադրում է՝ ",
"Launch pad":"Արձակման հարթակ",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Շտաբի կողքին գտնվող հորան՝ այստեղից երկնային պորտալով դեպի թիրախ են թռչում պարկուճները, մատակարարման արկղերն ու ռմբակոծիչները։ Վրան կառուցել չի կարելի։",
"Economy":"Տնտեսություն",
"Key building":"Առանցքային շենք",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Թույլ կետը՝ թիկունքը (շարժիչը)․ վնաս ×{0}։ Թնդանոթ, 2 գնդացրային աշտարակիկ, հրթիռային կասետ․ շատ դանդաղ է պտտվում՝ շրջանցիր կողքից։",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Թույլ կետը՝ փորի տակի լուսավոր կորիզը․ վնաս ներքևից ×{0}։ Աղավաղման ճառագայթ և մակերեսային տրորում․ քայլում է արգելապատնեշների վրայով, պահիր հեռավորություն և մի կուտակվիր։",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Դեմ՝ ավիառումբեր և հրետանի (×{0}), հրթիռներ (×{1}), գորգային ռմբակոծում․ գնդակները գրեթե անօգուտ են (×{2})։",
"Faction":"Խմբակցություն",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Արագ մեքենաներ, դրոնների երամներ, թունելներ և վերականգնում։ Հետևակն ավելի թեթև է, բայց արագ․ թնդանոթներն ու ռելսերն ավելի ուժեղ են խփում։",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Ծանր հետևակ ուժային զրահով, բետոնե արգելապատնեշներ, վերանորոգում և հրետանի։ Ավելի դանդաղ է, բայց ամուր։",
