"📖 Encyclopedia — in the pause menu (Esc): units, bosses, anomalies":"📖 Հանրագիտարան — դադարի ընտրացանկում (Esc). զորամիավորումներ, ղեկավարներ, անոմալիաներ",
"Tablet":"Պլանշետ",
