"1. Start a screen recording with your voice (PC — OBS, phone — the built-in screen recorder with mic) and turn on Feedback mode here.":"1. Միացրու էկրանի ձայնագրությունը ձայնով (ՀԱ-ում՝ OBS, հեռախոսում՝ ներկառուցված ձայնագրիչը խոսափողով) և այստեղ միացրիր «Կարծիքի ռեժիմը»։",
"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Խաղա և մտածիր բարձրաձայն. ինչն է անհասկանալի, ինչն է նյարդայնացնում, ինչն է դուր գալիս։ Անկյունում երևում են տարբերակը, ժամը և FPS. դրանցով ձայնագրությունը համադրվում է նշումների հետ։",
"3. When something matters — take a note: PC ":"3. Երբ ինչ-որ կարևոր բան լինի՝ արա նշում. ՀԱ ",
" (press ":" (նորից սեղմիր՝ ",
" again to add text), gamepad — hold View and press Start, phone — the ✎ button.":" տեքստ ավելացնելու համար), գեյմփադ՝ պահիր View և սեղմիր Start, հեռախոս՝ ✎ կոճակը։",
"4. After playing: Download all and send the file to Claude together with the recording.":"4. Խաղից հետո. «Ներբեռնել բոլորը» և ուղարկիր ֆայլը Claude-ին ձայնագրության հետ միասին։",
