"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Նայում ես վերևից և հրամանատարում ամբողջ բանակը. կառուցում ես բազան, ուղարկում ջոկատներ։ Բանակը առանց քեզ էլ ինքնուրույն կռվում է։",
