"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"Հուշումը ծալված է. «?»-ը նորից կբացի այն։ Դասից դուրս գալու համար՝ ☰ → «Դուրս գալ դասից»",
